struct game_control { int name; int type; void *mapping; };
struct value_type { const int first; game_control second; };
struct node {
  int color;
  node *parent;
  node *left;
  node *right;
  value_type value;
};
struct tree { node *header; unsigned int node_count; };
struct iterator {
  node *current;
  iterator(node *x) : current(x) {}
  iterator(const iterator &x) : current(x.current) {}
  iterator &operator--() {
    if (current->color == 0 && current->parent->parent == current)
      current = current->right;
    else if (current->left != 0) {
      node *y = current->left;
      while (y->right != 0)
        y = y->right;
      current = y;
    } else {
      node *y = current->parent;
      while (current == y->left) {
        current = y;
        y = y->parent;
      }
      current = y;
    }
    return *this;
  }
};

