iterator *insert_unique_hint(iterator *out, tree *self,
                             const iterator &position,
                             const value_type &v) {
  if (position.current == self->header->left) {
    if (self->node_count > 0 && v.first < position.current->value.first)
      return tree_insert(out, self, position.current, position.current, v);
    else {
      iterator tmp((node *)0);
      insert_unique_value(&tmp, self, v);
      out->current = tmp.current;
      return out;
    }
  } else if (position.current == self->header) {
    if (self->header->right->value.first < v.first)
      return tree_insert(out, self, 0, self->header->right, v);
    else {
      iterator tmp((node *)0);
      insert_unique_value(&tmp, self, v);
      out->current = tmp.current;
      return out;
    }
  } else {
    iterator before = position;
    --before;
    if (before.current->value.first < v.first &&
        v.first < position.current->value.first) {
      if (before.current->right == 0)
        return tree_insert(out, self, 0, before.current, v);
      else
        return tree_insert(out, self, position.current, position.current, v);
    } else {
      iterator tmp((node *)0);
      insert_unique_value(&tmp, self, v);
      out->current = tmp.current;
      return out;
    }
  }
}
